    /// </summary>
    private static readonly DiagnosticDescriptor ReasonGuaranteedByCtor = new(
        id: "EAG000",
        title: "EffectOverride reason 由构造子强制非空",
        messageFormat: "[EffectOverride] reason 非空由 L1 构造子强制（§8.3.1 不变式(1)），编译期无需诊断。",
        category: "EffectAlgebra",
        DiagnosticSeverity.Info,
        isEnabledByDefault: true);

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        // ① 识别标注：收集带 [EffectOverride] / [AcceptDeviation] 的 MethodDeclarationSyntax。
        var methods = context.SyntaxProvider.Create(
                predicate: static (node, _) => node is MethodDeclarationSyntax m && m.AttributeLists.Count > 0,
                transform: static (ctx, _) => GetAnnotatedMethod(ctx))
            .Where(static m => m is not null)
            .Select(static (m, _) => m!);

        // ② 生成注册桩：每个标注方法生成一个 partial 桩（§L2 翻译层；诚实声明残差）。
        context.RegisterSourceOutput(methods, static (spc, method) =>
        {
            var source = GenerateStub(method);
            spc.AddSource($"{method.MethodName}.g.cs", SourceText.From(source, Encoding.UTF8));
        });
    }

    /// <summary>§8.3 — 仅挑选带 [EffectOverride]/[AcceptDeviation] 的方法；其余忽略。</summary>
    private static AnnotatedMethod? GetAnnotatedMethod(GeneratorSyntaxContext ctx)
    {
        var method = (MethodDeclarationSyntax)ctx.Node;
        bool hasOverride = false, hasAccept = false;
        foreach (var attr in method.AttributeLists.SelectMany(l => l.Attributes))
        {
            if (HasAttributeName(attr.Name, EffectOverrideName)) hasOverride = true;
            else if (HasAttributeName(attr.Name, AcceptDeviationName)) hasAccept = true;
        }
